CREATE USER olrt_rb IDENTIFIED BY olrt QUOTA UNLIMITED ON users DEFAULT TABLESPACE users;
-- PCTFREE 0: growing UPDATEs migrate rows
CREATE TABLE olrt_rb.mig (id NUMBER(10) PRIMARY KEY, a VARCHAR2(2000), b VARCHAR2(2000), n NUMBER(10)) PCTFREE 0;
INSERT INTO olrt_rb.mig SELECT LEVEL, NULL, NULL, LEVEL FROM dual CONNECT BY LEVEL <= 400;
