INSERT INTO olrt_rb.wide (id, c2, c150, c260, c300) SELECT LEVEL, 'a', 'b', 'c', 'd' FROM dual CONNECT BY LEVEL <= 200;
CREATE TABLE olrt_rb.part (id NUMBER(10) PRIMARY KEY, region NUMBER(3), txt VARCHAR2(30))
  PARTITION BY RANGE (region) (PARTITION p1 VALUES LESS THAN (10), PARTITION p2 VALUES LESS THAN (20), PARTITION p3 VALUES LESS THAN (MAXVALUE)) ENABLE ROW MOVEMENT;
INSERT INTO olrt_rb.part SELECT LEVEL, MOD(LEVEL, 25), 'p' || LEVEL FROM dual CONNECT BY LEVEL <= 200;
CREATE TABLE olrt_rb.iot (id NUMBER(10) PRIMARY KEY, txt VARCHAR2(100), n NUMBER(10)) ORGANIZATION INDEX;
INSERT INTO olrt_rb.iot SELECT LEVEL, 'i' || LEVEL, LEVEL FROM dual CONNECT BY LEVEL <= 200;
CREATE TABLE olrt_rb.lobt (id NUMBER(10) PRIMARY KEY, txt VARCHAR2(30), c CLOB);
INSERT INTO olrt_rb.lobt SELECT LEVEL, 'l' || LEVEL, 'small clob ' || LEVEL FROM dual CONNECT BY LEVEL <= 100;
CREATE TABLE olrt_rb.bc (id NUMBER(10) PRIMARY KEY, txt VARCHAR2(40), n NUMBER(10)) COMPRESS BASIC;
INSERT /*+ APPEND */ INTO olrt_rb.bc SELECT LEVEL, 'same text', 1 FROM dual CONNECT BY LEVEL <= 300;
COMMIT;
CREATE TABLE olrt_rb.parent (id NUMBER(10) PRIMARY KEY, txt VARCHAR2(30));
CREATE TABLE olrt_rb.child (id NUMBER(10) PRIMARY KEY, parent_id NUMBER(10) REFERENCES olrt_rb.parent ON DELETE CASCADE, txt VARCHAR2(30));
CREATE TABLE olrt_rb.aud (id NUMBER(10) GENERATED ALWAYS AS IDENTITY PRIMARY KEY, parent_id NUMBER(10), act VARCHAR2(10));
INSERT INTO olrt_rb.parent SELECT LEVEL, 'pa' || LEVEL FROM dual CONNECT BY LEVEL <= 50;
INSERT INTO olrt_rb.child SELECT LEVEL, MOD(LEVEL, 50) + 1, 'ch' || LEVEL FROM dual CONNECT BY LEVEL <= 150;
CREATE OR REPLACE TRIGGER olrt_rb.parent_aud AFTER UPDATE OR DELETE ON olrt_rb.parent FOR EACH ROW
DECLARE
  act VARCHAR2(1) := 'D';
BEGIN
  IF UPDATING THEN act := 'U'; END IF;
  INSERT INTO olrt_rb.aud (parent_id, act) VALUES (:OLD.id, act);
END;
/
ALTER TABLE olrt_rb.mig ADD SUPPLEMENTAL LOG DATA (ALL) COLUMNS;
ALTER TABLE olrt_rb.wide ADD SUPPLEMENTAL LOG DATA (ALL) COLUMNS;
ALTER TABLE olrt_rb.part ADD SUPPLEMENTAL LOG DATA (ALL) COLUMNS;
ALTER TABLE olrt_rb.iot ADD SUPPLEMENTAL LOG DATA (ALL) COLUMNS;
ALTER TABLE olrt_rb.lobt ADD SUPPLEMENTAL LOG DATA (ALL) COLUMNS;
ALTER TABLE olrt_rb.bc ADD SUPPLEMENTAL LOG DATA (ALL) COLUMNS;
